const {chromium}=require(process.env.ADC_PLAYWRIGHT_MODULE || 'playwright');
const crypto=require('node:crypto');
const fs=require('node:fs');
const cp=require('node:child_process');
const path=require('node:path');
const root=path.resolve(__dirname,'../../../..');
process.chdir(root);
fs.mkdirSync('work',{recursive:true,mode:0o700});
let server,browser;
(async()=>{
 const dir=fs.mkdtempSync('work/ui-run-');
 server=cp.spawn('./bin/adc',['serve','-addr','127.0.0.1:8790','-data',dir],{stdio:['ignore','pipe','inherit']});
 await new Promise((resolve,reject)=>{server.stdout.once('data',resolve);server.once('error',reject);server.once('exit',code=>reject(new Error('server exited '+code)));});
 browser=await chromium.launch({headless:true});
 const context=await browser.newContext({viewport:{width:1440,height:1000}});
 const page=await context.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:8790/');
 await page.getByLabel('Your name',{exact:true}).fill('UI verification');
 await page.getByLabel('Organization',{exact:true}).fill('Interface QA fixture');
 await page.getByLabel('Username',{exact:true}).fill('ui-test');
 await page.getByLabel('Password',{exact:true}).fill(crypto.randomBytes(24).toString('hex'));
 await page.getByRole('button',{name:'Create workspace'}).click();
 await page.getByRole('heading',{name:'Work in motion.'}).waitFor();
 await page.screenshot({path:'work/ui-desktop.png',fullPage:true});
 await page.getByRole('link',{name:'Team',exact:true}).click();
 await page.getByRole('button',{name:'Add agent'}).click();
 await page.getByLabel('Name / title',{exact:true}).fill('Review specialist');
 await page.getByLabel('Responsibilities',{exact:true}).fill('Review evidence and verify that claims match the shipped product.');
 await page.getByLabel(/^Work category/).selectOption('review');
 await page.getByLabel('Model ID',{exact:true}).fill('claude-opus-5');
 await page.getByRole('button',{name:'Create agent',exact:true}).click();
 await page.getByRole('heading',{name:'Review specialist',exact:true}).waitFor();
 await page.getByRole('button',{name:'Edit configuration'}).click();
 await page.getByRole('button',{name:'Save changes'}).click();
 await page.getByRole('heading',{name:'Review specialist',exact:true}).waitFor();
 await page.screenshot({path:'work/ui-team-desktop.png',fullPage:true});
 await page.setViewportSize({width:390,height:844});
 await page.screenshot({path:'work/ui-mobile.png',fullPage:true});
 const overflow=await page.evaluate(()=>document.documentElement.scrollWidth>window.innerWidth);
 console.log(JSON.stringify({errors,mobileOverflow:overflow,teamCreated:true,agentEdited:true}));
 await browser.close();server.kill('SIGTERM');if(errors.length||overflow)process.exitCode=1;
})().catch(async e=>{console.error(e);if(browser)await browser.close();if(server)server.kill('SIGTERM');process.exitCode=1});
